// v0.4 hero collection. Pure data/reducers; the engine supplies RNG and time.
import type { Rng } from './rng.js';
import type { MonsterType } from './types-chart.js';
import type { GameEvent, GameState } from './types.js';
import { monsterForIndex } from './monsters.js';

export interface HeroRoll { formId: string; buffPercent: number }
export interface HeroForm {
  id: string;
  name: string;
  rank: number;
  type: MonsterType;
  buff: 'element' | 'party';
}
export interface HeroProgress {
  equipped: HeroRoll;
  collection: HeroRoll[];
  reincarnations: number;
  choices: HeroRoll[];
  deferRemainingMs: number;
  /** Successful reincarnation cadence, independent of the short free deferral. */
  restRemainingMs?: number;
  /** Prevents a queued click from spending gold or choosing a different offer. */
  offerSerial: number;
}
export type HeroAction =
  | { type: 'heroOffer' }
  | { type: 'heroChoose'; formId: string; offerSerial: number }
  | { type: 'heroReroll'; offerSerial: number }
  | { type: 'heroDefer'; offerSerial: number }
  | { type: 'heroEquip'; formId: string };

const ARCHETYPES = [
  ['여명검사', 'fire'], ['파도창기사', 'water'], ['바람궁수', 'wind'],
  ['숲수호자', 'earth'], ['달그림자', 'dark'], ['화염도끼전사', 'fire'],
  ['서리마도사', 'water'], ['폭풍쌍검사', 'wind'], ['수정망치기사', 'earth'],
  ['밤소환사', 'dark'],
] as const;
const RANKS = ['새벽', '서약', '왕실', '천상', '신화'] as const;
export const HERO_FORMS: readonly HeroForm[] = Object.freeze(Array.from({ length: 50 }, (_, i) => {
  const archetype = ARCHETYPES[i % 10]!;
  return Object.freeze({
    id: `h${String(i + 1).padStart(2, '0')}`,
    name: `${RANKS[Math.floor(i / 10)]} ${archetype[0]}`,
    rank: Math.floor(i / 10) + 1,
    type: archetype[1],
    buff: i % 10 < 5 ? 'element' as const : 'party' as const,
  });
}));
export const HERO_MIN_LEVEL = 12;
export const HERO_DEFER_MS = 30_000;
export const HERO_REST_MS = 120_000;
export const HERO_BUFF_MIN = 10;
export const HERO_BUFF_MAX = 25;
export const heroForm = (id: string): HeroForm | undefined => HERO_FORMS.find((f) => f.id === id);
export const newHeroProgress = (): HeroProgress => ({
  equipped: { formId: 'h00', buffPercent: 0 }, collection: [], reincarnations: 0,
  choices: [], deferRemainingMs: 0, offerSerial: 0,
});
export const heroRerollCost = (reincarnations: number): number => 50 + 25 * Math.min(100, reincarnations);
export const heroReady = (level: number, hero?: HeroProgress): boolean =>
  level >= HERO_MIN_LEVEL && (hero?.deferRemainingMs ?? 0) <= 0 && (hero?.restRemainingMs ?? 0) <= 0;
export const copyHeroProgress = (hero: HeroProgress): HeroProgress => ({ ...hero,
  equipped: { ...hero.equipped }, collection: hero.collection.map((r) => ({ ...r })), choices: hero.choices.map((r) => ({ ...r })) });

/** Early familiar hits; from level 3 on each level adds a growing damage gain. */
export const heroDamageForLevel = (level: number): bigint => {
  const n = BigInt(Math.max(1, Math.floor(level)));
  const growth = n > 2n ? n - 2n : 0n;
  return n + growth * growth;
};
export const heroAttackPower = (level: number, souls = 0, reincarnations = 0): bigint =>
  heroDamageForLevel(level) * BigInt(1 + souls) * BigInt(100 + 25 * reincarnations) / 100n;

export function isHeroRoll(value: unknown): value is HeroRoll {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) return false;
  const r = value as Record<string, unknown>;
  return typeof r['formId'] === 'string' && typeof r['buffPercent'] === 'number' &&
    Number.isInteger(r['buffPercent']) && (r['formId'] === 'h00'
      ? r['buffPercent'] === 0
      : heroForm(r['formId']) !== undefined && r['buffPercent'] >= HERO_BUFF_MIN && r['buffPercent'] <= HERO_BUFF_MAX);
}
export function heroBuffedPower(base: bigint, type: MonsterType, roll?: HeroRoll): bigint {
  if (!roll || !isHeroRoll(roll)) return base;
  const form = heroForm(roll.formId);
  const bonus = form?.buff === 'party' ? roll.buffPercent : form?.type === type ? 2 * roll.buffPercent : 0;
  return base * BigInt(100 + bonus) / 100n;
}

/** Missing hero means a legacy save; invalid subfields never erase other progress. */
export function parseHeroProgress(value: unknown): HeroProgress | undefined {
  if (value === undefined) return undefined;
  const h = typeof value === 'object' && value !== null ? value as Record<string, unknown> : {};
  const int = (key: string, max: number): number => {
    const n = h[key];
    return typeof n === 'number' && Number.isSafeInteger(n) ? Math.max(0, Math.min(max, n)) : 0;
  };
  const rolls = (value: unknown, cap: number): HeroRoll[] => {
    const kept: HeroRoll[] = [];
    if (!Array.isArray(value)) return kept;
    for (const r of value) {
      if (!isHeroRoll(r) || r.formId === 'h00') continue;
      const old = kept.find((x) => x.formId === r.formId);
      if (old) old.buffPercent = Math.max(old.buffPercent, r.buffPercent);
      else if (kept.length < cap) kept.push({ formId: r.formId, buffPercent: r.buffPercent });
    }
    return kept;
  };
  const collection = rolls(h['collection'], 50);
  const equipped = isHeroRoll(h['equipped']) ? h['equipped'] : newHeroProgress().equipped;
  const owned = collection.find((r) => r.formId === equipped.formId);
  const reincarnations = int('reincarnations', 1_000_000);
  const choices = rolls(h['choices'], 3).filter((r) => heroForm(r.formId)!.rank <= Math.min(5, reincarnations + 1));
  const remaining = h['deferRemainingMs'];
  const deferRemainingMs = typeof remaining === 'number' && Number.isFinite(remaining)
    ? Math.max(0, Math.min(HERO_DEFER_MS, Math.ceil(remaining))) : 0;
  const rest = h['restRemainingMs'];
  const restRemainingMs = typeof rest === 'number' && Number.isFinite(rest)
    ? Math.max(0, Math.min(HERO_REST_MS, Math.ceil(rest))) : 0;
  return {
    equipped: owned ? { ...owned } : { formId: 'h00', buffPercent: 0 }, collection,
    reincarnations, choices: choices.length === 3 && deferRemainingMs === 0 && restRemainingMs === 0 ? choices : [],
    deferRemainingMs, offerSerial: int('offerSerial', Number.MAX_SAFE_INTEGER - 1),
    ...(h['restRemainingMs'] !== undefined ? { restRemainingMs } : {}),
  };
}

/** 3 different elements; top unlocked rank guaranteed; unowned forms preferred. */
export function rollHeroChoices(hero: HeroProgress, rng: Rng): HeroRoll[] {
  const rank = Math.min(5, hero.reincarnations + 1);
  const picked: HeroRoll[] = [];
  const types = new Set<MonsterType>();
  for (let i = 0; i < 3; i++) {
    let pool = HERO_FORMS.filter((f) => f.rank <= rank && !types.has(f.type) && (i !== 0 || f.rank === rank));
    const unseen = pool.filter((f) => !hero.collection.some((r) => r.formId === f.id));
    if (unseen.length > 0) pool = unseen;
    const f = pool[Math.min(pool.length - 1, Math.floor(rng.next() * pool.length))]!;
    types.add(f.type);
    picked.push({ formId: f.id, buffPercent: HERO_BUFF_MIN + Math.min(15, Math.floor(rng.next() * 16)) });
  }
  return picked;
}

export function applyHeroAction(state: Readonly<GameState>, action: HeroAction, rng: Rng):
  { state: GameState; events: GameEvent[] } | { error: string } {
  const hero = state.hero ? copyHeroProgress(state.hero) : newHeroProgress();
  const result = (patch: Partial<GameState> = {}, events: GameEvent[] = []) => ({
    state: { ...state, hero, ...patch }, events,
  });
  if (action.type === 'heroEquip') {
    const owned = hero.collection.find((r) => r.formId === action.formId);
    if (!owned) return { error: 'Uncollected hero form' };
    hero.equipped = { ...owned };
    return result();
  }
  if (!heroReady(state.level, hero)) return { error: 'Hero reincarnation is not ready' };
  if (action.type === 'heroOffer') {
    if (hero.choices.length > 0) return { error: 'An offer is already open' };
    hero.choices = rollHeroChoices(hero, rng);
    hero.offerSerial++;
    return result();
  }
  if (hero.choices.length !== 3 || action.offerSerial !== hero.offerSerial) return { error: 'Stale hero offer' };
  if (action.type === 'heroDefer') {
    hero.choices = [];
    hero.deferRemainingMs = HERO_DEFER_MS;
    return result();
  }
  if (action.type === 'heroReroll') {
    const cost = heroRerollCost(hero.reincarnations);
    if (state.coins < cost) return { error: 'Not enough gold' };
    hero.choices = rollHeroChoices(hero, rng);
    hero.offerSerial++;
    return result({ coins: state.coins - cost });
  }
  const selected = hero.choices.find((r) => r.formId === action.formId);
  if (!selected) return { error: 'Hero is not in this offer' };
  const owned = hero.collection.find((r) => r.formId === selected.formId);
  if (owned) owned.buffPercent = Math.max(owned.buffPercent, selected.buffPercent);
  else hero.collection.push({ ...selected });
  hero.equipped = { ...(owned ?? selected) };
  hero.reincarnations++;
  hero.restRemainingMs = HERO_REST_MS;
  hero.choices = [];
  const monster = monsterForIndex(0);
  const souls = state.souls + Math.max(1, Math.floor(state.monster.index / 8));
  return result({ level: 1, xp: 0, monster, monsterHp: monster.maxHp, souls,
    rebirths: state.rebirths + 1 }, [{ type: 'rebirth', souls }]);
}

import { describe, expect, it } from 'vitest';
import {
  createEngine, DEFAULT_SAVE, HERO_FORMS, HERO_DEFER_MS, HERO_MIN_LEVEL,
  heroAttackPower, heroBuffedPower, heroDamageForLevel, heroForm,
  heroRerollCost, mulberry32, newHeroProgress, parseSave, serializeSave,
} from '../src/core/index.js';
import type { SaveFile } from '../src/core/index.js';

const readySave = (): SaveFile => ({ ...DEFAULT_SAVE, level: HERO_MIN_LEVEL, coins: 1000, monsterIndex: 39, monsterHp: '1',
  companions: [{ id: 'c1', speciesId: 'dragon', bossIndex: 31, level: 3, stars: 1 }], pvpParty: ['c1'], nextCompanionId: 2 });
const readyEngine = () => createEngine(readySave(), mulberry32(4));

describe('v0.4 hero growth, collection and persistent choices', () => {
  it('gives every level a strictly larger hit and accelerates beyond the old linear curve', () => {
    expect(heroDamageForLevel(1)).toBe(1n);
    expect(heroDamageForLevel(2)).toBe(2n);
    expect(heroDamageForLevel(10)).toBe(74n);
    for (let level = 2; level <= 100; level++) expect(heroDamageForLevel(level)).toBeGreaterThan(heroDamageForLevel(level - 1));
    expect(heroAttackPower(10, 2, 4)).toBe(444n);
    const engine = createEngine({ ...DEFAULT_SAVE, level: 10 }, { next: () => .99 });
    expect(engine.attack('keyboard')[0]).toMatchObject({ type: 'attack', damage: 74n });
  });
  it('defines 50 fixed form/element/buff sets across five visual ranks', () => {
    expect(HERO_FORMS).toHaveLength(50);
    expect(new Set(HERO_FORMS.map((f) => f.id)).size).toBe(50);
    for (let rank = 1; rank <= 5; rank++) {
      const forms = HERO_FORMS.filter((f) => f.rank === rank);
      expect(forms).toHaveLength(10);
      expect(new Set(forms.map((f) => f.type)).size).toBe(5);
      expect(forms.filter((f) => f.buff === 'element')).toHaveLength(5);
    }
  });
  it('requires the unlock, rolls 3 different elements and persists the exact offer on reload', () => {
    const locked = createEngine({ ...DEFAULT_SAVE, level: HERO_MIN_LEVEL - 1 }, mulberry32(4));
    locked.apply({ type: 'heroOffer' });
    expect(locked.getState().hero).toBeUndefined();
    const engine = readyEngine();
    engine.apply({ type: 'heroOffer' });
    const offered = engine.toSave();
    expect(offered.hero?.choices).toHaveLength(3);
    expect(new Set(offered.hero?.choices.map((c) => heroForm(c.formId)?.type)).size).toBe(3);
    const resumed = createEngine(parseSave(serializeSave(offered)), mulberry32(987));
    resumed.apply({ type: 'heroOffer' });
    expect(resumed.toSave()).toEqual(offered);
    for (const c of offered.hero!.choices) expect(c.buffPercent).toBeGreaterThanOrEqual(10);
  });
  it('spends exactly once on a current offer, refuses insufficient gold and stale double clicks', () => {
    const engine = readyEngine();
    engine.apply({ type: 'heroOffer' });
    const offered = engine.toSave().hero!;
    engine.apply({ type: 'heroReroll', offerSerial: offered.offerSerial });
    expect(engine.getState().coins).toBe(1000 - heroRerollCost(0));
    const rerolled = engine.toSave();
    engine.apply({ type: 'heroReroll', offerSerial: offered.offerSerial });
    engine.apply({ type: 'heroChoose', formId: offered.choices[0]!.formId, offerSerial: offered.offerSerial });
    expect(engine.toSave()).toEqual(rerolled);
    const poor = createEngine({ ...rerolled, coins: 49 }, mulberry32(7));
    const before = poor.toSave();
    poor.apply({ type: 'heroReroll', offerSerial: rerolled.hero!.offerSerial });
    expect(poor.toSave()).toEqual(before);
  });
  it('deferring preserves progress and enables a free new opportunity after 30 injected seconds, including reload', () => {
    const engine = createEngine({ ...readySave(), companions: [], pvpParty: [] }, mulberry32(4));
    engine.apply({ type: 'heroOffer' });
    engine.apply({ type: 'heroDefer', offerSerial: engine.getState().hero!.offerSerial });
    expect(engine.getState()).toMatchObject({ level: HERO_MIN_LEVEL, coins: 1000, hero: { choices: [], deferRemainingMs: HERO_DEFER_MS } });
    engine.tick(17.5);
    const resumed = createEngine(parseSave(serializeSave(engine.toSave())), mulberry32(9));
    resumed.apply({ type: 'heroOffer' });
    expect(resumed.getState().hero!.choices).toHaveLength(0);
    resumed.tick(29_982);
    expect(resumed.getState().hero!.choices).toHaveLength(0);
    expect(resumed.tick(1)).toContainEqual({ type: 'heroReady' });
    resumed.apply({ type: 'heroOffer' });
    expect(resumed.getState().hero!.choices).toHaveLength(3);
    expect(resumed.getState().coins).toBe(1000);
  });
  it('only acceptance resets the run, retains possessions, equips and raises the next visual rank', () => {
    const engine = readyEngine();
    engine.apply({ type: 'heroOffer' });
    const before = engine.toSave();
    const choice = before.hero!.choices[0]!;
    engine.apply({ type: 'heroChoose', formId: 'h50', offerSerial: before.hero!.offerSerial });
    expect(engine.toSave()).toEqual(before);
    expect(engine.apply({ type: 'heroChoose', formId: choice.formId, offerSerial: before.hero!.offerSerial })).toContainEqual({ type: 'rebirth', souls: 4 });
    const accepted = engine.toSave();
    expect(accepted).toMatchObject({ level: 1, xp: 0, monsterIndex: 0, coins: before.coins, companions: before.companions,
      pvpParty: before.pvpParty, hero: { equipped: choice, collection: [choice], reincarnations: 1, choices: [] } });
    const next = createEngine({ ...accepted, level: HERO_MIN_LEVEL, companions: [], pvpParty: [] }, mulberry32(3));
    next.apply({ type: 'heroOffer' });
    expect(next.getState().hero!.choices).toHaveLength(0);
    next.tick(120_000);
    next.apply({ type: 'heroOffer' });
    expect(heroForm(next.getState().hero!.choices[0]!.formId)?.rank).toBe(2);
    const saved = next.toSave();
    saved.hero!.collection[0]!.buffPercent = 999;
    expect(next.getState().hero!.collection[0]!.buffPercent).toBe(choice.buffPercent);
  });
  it('equips only collected skins and keeps their fixed roll without resetting the run', () => {
    const hero = { ...newHeroProgress(), equipped: { formId: 'h01', buffPercent: 10 },
      collection: [{ formId: 'h01', buffPercent: 10 }, { formId: 'h09', buffPercent: 25 }] };
    const engine = createEngine({ ...readySave(), hero }, mulberry32(2));
    engine.apply({ type: 'heroEquip', formId: 'h50' });
    expect(engine.getState().hero!.equipped.formId).toBe('h01');
    engine.apply({ type: 'heroEquip', formId: 'h09' });
    expect(engine.getState()).toMatchObject({ level: HERO_MIN_LEVEL, coins: 1000, hero: { equipped: { formId: 'h09', buffPercent: 25 } } });
  });
  it('retains the best roll on duplicates instead of downgrading an owned form', () => {
    const hero = { ...newHeroProgress(), collection: [{ formId: 'h01', buffPercent: 25 }],
      choices: [{ formId: 'h01', buffPercent: 10 }, { formId: 'h02', buffPercent: 15 }, { formId: 'h03', buffPercent: 20 }], offerSerial: 1 };
    const engine = createEngine({ ...readySave(), hero }, mulberry32(2));
    engine.apply({ type: 'heroChoose', formId: 'h01', offerSerial: 1 });
    expect(engine.getState().hero!.equipped).toEqual({ formId: 'h01', buffPercent: 25 });
    expect(engine.getState().hero!.collection).toHaveLength(1);
  });
  it('specialists and generalists produce different useful parties, without a rarity multiplier', () => {
    expect(heroBuffedPower(100n, 'fire', { formId: 'h01', buffPercent: 25 })).toBe(150n);
    expect(heroBuffedPower(100n, 'water', { formId: 'h01', buffPercent: 25 })).toBe(100n);
    expect(heroBuffedPower(100n, 'water', { formId: 'h06', buffPercent: 25 })).toBe(125n);
    expect(heroBuffedPower(100n, 'fire', { formId: 'h41', buffPercent: 25 })).toBe(150n);
    expect(heroBuffedPower(100n, 'fire', { formId: 'h01', buffPercent: 99 })).toBe(100n);
  });
  it('validates malformed hero fields independently and never changes legacy progress', () => {
    const legacy = readySave();
    expect(parseSave(serializeSave(legacy))).toEqual(legacy);
    const parsed = parseSave({ ...legacy, hero: { equipped: { formId: 'h50', buffPercent: 100 },
      collection: [{ formId: 'h01', buffPercent: 10 }, { formId: 'h01', buffPercent: 25 }, { formId: '__proto__', buffPercent: 10 }],
      choices: [{ formId: 'h50', buffPercent: 20 }], deferRemainingMs: Infinity, reincarnations: -1 } });
    expect(parsed.hero).toMatchObject({ equipped: { formId: 'h00', buffPercent: 0 }, collection: [{ formId: 'h01', buffPercent: 25 }], choices: [], reincarnations: 0, deferRemainingMs: 0 });
    expect(parsed.coins).toBe(legacy.coins);
    expect(parsed.companions).toEqual(legacy.companions);
  });
});

import { describe, expect, it, vi } from 'vitest';
import { createApp, PVP_COOLDOWN_MS } from '../../src/server/app.js';
import { MemoryStore } from '../../src/server/store.js';
import { simulateBattle } from '../../src/core/battle.js';
import type { ApiRequest, ApiResponse } from '../../src/server/http.js';
import type { Companion, MatchResponse, OpponentListResult, PvpResponse, RegisterResponse } from '../../src/shared/api.js';

const companion = (id: string, bossIndex = 8): Companion => ({ id, speciesId: 'slime', bossIndex, level: 1, stars: 0 });
function setup() {
  const store = new MemoryStore();
  let ids = 0;
  let now = 1_700_000_000_000;
  const { handle } = createApp({ store, now: () => now, randomUUID: () => `u${ids++}`, randomBytesHex: (n) => (ids++).toString(16).padStart(n * 2, '0'), randomSeed: () => 7 });
  const call = (method: string, path: string, auth: string | null = null, body: unknown = null): Promise<ApiResponse> => handle({ method, path, auth, body, query: {}, ip: 'test' } as ApiRequest);
  const player = async (name: string, bestIndex: number, companions: Companion[] = []) => {
    const { playerId, token } = (await call('POST', '/v1/players', null, { nickname: name })).body as RegisterResponse;
    const snapshot = { name, bestIndex, rebirths: 0, companions, party: companions.map((c) => c.id) };
    expect((await call('PUT', '/v1/snapshot', token, snapshot)).status).toBe(200);
    return { playerId, token, snapshot };
  };
  const list = async (token: string) => (await call('GET', '/v1/pvp/opponents', token)).body as OpponentListResult;
  const preview = async (token: string, opponentId?: string) => (await call('POST', '/v1/pvp/match', token, { opponentId })).body as MatchResponse;
  const fight = async (token: string, matchId: string) => call('POST', '/v1/pvp', token, { matchId, party: [] });
  return { store, call, player, list, preview, fight, advance: () => { now += PVP_COOLDOWN_MS; } };
}

describe('v0.4 opponent directory and official records', () => {
  it('lists, previews and steals from a legacy persisted snapshot without a party field', async () => {
    const s = setup();
    const me = await s.player('me', 1, [companion('a1', 400)]);
    const foe = await s.player('old', 2, [companion('d1')]);
    const legacy = (await s.store.getById(foe.playerId))?.snapshot;
    if (!legacy) throw new Error('fixture missing');
    Reflect.deleteProperty(legacy, 'party');
    expect((await s.list(me.token)).opponents[0]?.party).toEqual([companion('d1')]);
    const match = await s.preview(me.token, foe.playerId);
    expect(match.opponent.party).toEqual([companion('d1')]);
    const result = await s.fight(me.token, match.matchId);
    expect(result.status).toBe(200);
    expect((result.body as PvpResponse).stolen?.id).toBe('s7');
    expect((await s.store.getById(foe.playerId))?.snapshot?.party).toEqual([]);
  });

  it('caps the directory at 50 opponents without spending a slot on the caller', async () => {
    const s = setup();
    const me = await s.player('me', 999);
    for (let i = 0; i < 52; i += 1) await s.player(`rival${i}`, i);
    const { opponents } = await s.list(me.token);
    expect(opponents).toHaveLength(50);
    expect(opponents.some((row) => row.playerId === me.playerId)).toBe(false);
    expect(opponents[0]).toMatchObject({ name: 'rival51', rank: 2 });
    expect(opponents.at(-1)).toMatchObject({ name: 'rival2', rank: 51 });
  });

  it('lists other players with actual party, hero and tie-aware rank; legacy hero defaults to novice', async () => {
    const s = setup();
    const me = await s.player('me', 4);
    const foe = await s.player('foe', 9, [companion('c1'), companion('c2')]);
    const tied = await s.player('tied', 9);
    await s.call('PUT', '/v1/snapshot', foe.token, { ...foe.snapshot, party: ['c2'], hero: { formId: 'h06', buffPercent: 25 }, wins: 999 });
    const result = await s.list(me.token);
    expect(result.opponents).toEqual([
      { playerId: foe.playerId, rank: 1, name: 'foe', bestIndex: 9, rebirths: 0, party: [companion('c2')], hero: { formId: 'h06', buffPercent: 25 }, wins: 0, losses: 0 },
      { playerId: tied.playerId, rank: 1, name: 'tied', bestIndex: 9, rebirths: 0, party: [], hero: { formId: 'h00', buffPercent: 0 }, wins: 0, losses: 0 },
    ]);
    expect((await s.call('GET', '/v1/pvp/opponents')).status).toBe(401);
  });

  it('validates catalog hero rolls and selected ids at the request boundary', async () => {
    const s = setup();
    const me = await s.player('me', 1);
    for (const hero of [null, { formId: 'evil', buffPercent: 10 }, { formId: 'h01', buffPercent: 100 }, { formId: 'h01', buffPercent: 10.5 }, { formId: 'h00', buffPercent: 10 }]) {
      expect((await s.call('PUT', '/v1/snapshot', me.token, { ...me.snapshot, hero })).status).toBe(400);
    }
    for (const opponentId of [me.playerId, 1, {}, 'bad/path']) expect((await s.call('POST', '/v1/pvp/match', me.token, { opponentId })).status).toBe(400);
    expect((await s.call('POST', '/v1/pvp/match', me.token, { opponentId: 'missing' })).status).toBe(404);
    expect((await s.list(me.token)).opponents).toEqual([]);
  });

  it('selects a distant player and binds its hero/party to the preview even after upload', async () => {
    const s = setup();
    const me = await s.player('me', 1, [companion('a1')]);
    await s.player('near', 2);
    const foe = await s.player('distant', 90, [companion('d1')]);
    const hero = { formId: 'h06', buffPercent: 25 };
    await s.call('PUT', '/v1/snapshot', foe.token, { ...foe.snapshot, hero });
    const match = await s.preview(me.token, foe.playerId);
    expect(match.opponent.name).toBe('distant');
    expect(match.opponent.hero).toEqual(hero);
    await s.call('PUT', '/v1/snapshot', foe.token, { ...foe.snapshot, companions: [], party: [], hero: { formId: 'h00', buffPercent: 0 } });
    const result = (await s.fight(me.token, match.matchId)).body as PvpResponse;
    expect(result.opponent.hero).toEqual(hero);
    expect(result.opponent.party).toEqual(match.opponent.party);
    const expected = simulateBattle(me.snapshot.companions, match.opponent.party, { defender: hero });
    expect(result.blows).toEqual(expected.blows.map((blow) => ({ ...blow, damage: String(blow.damage) })));
    expect(result.stolen).toBeNull();
  });

  it('counts actual wins and losses once, including defending wins, while training and previews count zero', async () => {
    const s = setup();
    const me = await s.player('me', 1, [companion('a1')]);
    const training = await s.preview(me.token);
    await s.fight(me.token, training.matchId);
    expect(await s.store.getById(me.playerId)).toMatchObject({ wins: 0, losses: 0 });
    s.advance();
    const foe = await s.player('foe', 20, [companion('d1', 400)]);
    const match = await s.preview(me.token, foe.playerId);
    expect((await s.list(me.token)).opponents[0]).toMatchObject({ wins: 0, losses: 0 });
    const results = await Promise.all([s.fight(me.token, match.matchId), s.fight(me.token, match.matchId)]);
    expect(results.map((r) => r.status).sort()).toEqual([200, 429]);
    expect(await s.store.getById(me.playerId)).toMatchObject({ wins: 0, losses: 1 });
    expect((await s.list(me.token)).opponents[0]).toMatchObject({ wins: 1, losses: 0 });
    // Self-reported stats cannot erase or inflate an official result.
    await s.call('PUT', '/v1/snapshot', foe.token, { ...foe.snapshot, wins: 1000, losses: 500 });
    expect((await s.list(me.token)).opponents[0]).toMatchObject({ wins: 1, losses: 0 });
  });

  it('serializes two attackers so a previewed companion can only be stolen once', async () => {
    const s = setup();
    const a = await s.player('a', 1, [companion('a1', 400)]);
    const b = await s.player('b', 2, [companion('b1', 400)]);
    const foe = await s.player('foe', 3, [companion('d1')]);
    const ma = await s.preview(a.token, foe.playerId);
    const mb = await s.preview(b.token, foe.playerId);
    const results = await Promise.all([s.fight(a.token, ma.matchId), s.fight(b.token, mb.matchId)]);
    expect(results.every((r) => r.status === 200)).toBe(true);
    expect(results.map((r) => (r.body as PvpResponse).stolen).filter(Boolean)).toHaveLength(1);
    expect(await s.store.getById(foe.playerId)).toMatchObject({ losses: 2, stolenIds: ['d1'] });
  });

  it('keeps transferred ids unique when independent battles repeat the same seed', async () => {
    const s = setup();
    const me = await s.player('me', 1, [companion('a1', 400)]);
    const first = await s.player('first', 2, [companion('d1')]);
    const second = await s.player('second', 3, [companion('d2')]);
    const m1 = await s.preview(me.token, first.playerId);
    const r1 = (await s.fight(me.token, m1.matchId)).body as PvpResponse;
    s.advance();
    const m2 = await s.preview(me.token, second.playerId);
    const r2 = (await s.fight(me.token, m2.matchId)).body as PvpResponse;
    expect(r1.stolen?.id).toBe('s7');
    expect(r2.stolen?.id).toMatch(/^s[0-9a-f]{14}$/);
    expect(r2.stolen?.id).not.toBe(r1.stolen?.id);
    const ids = (await s.store.getById(me.playerId))?.snapshot?.companions.map((c) => c.id);
    expect(ids).toHaveLength(3);
    expect(new Set(ids).size).toBe(3);
  });

  it('rolls back cooldown, records and every roster write when a store write fails', async () => {
    const s = setup();
    const me = await s.player('me', 1, [companion('a1', 400)]);
    const foe = await s.player('foe', 2, [companion('d1')]);
    const beforeMe = structuredClone(await s.store.getById(me.playerId));
    const beforeFoe = structuredClone(await s.store.getById(foe.playerId));
    const match = await s.preview(me.token, foe.playerId);
    vi.spyOn(s.store, 'setThefts').mockRejectedValueOnce(new Error('disk failed'));
    expect((await s.fight(me.token, match.matchId)).status).toBe(500);
    expect(await s.store.getById(me.playerId)).toEqual(beforeMe);
    expect(await s.store.getById(foe.playerId)).toEqual(beforeFoe);
    // The queue is released after a failed transaction; a fresh match works.
    const fresh = await s.preview(me.token, foe.playerId);
    expect((await s.fight(me.token, fresh.matchId)).status).toBe(200);
  });
});

