// The pg module is entirely replaced: these tests open no DB or socket.
const { commands, release, query, poolQuery } = vi.hoisted(() => {
  const commands: string[] = [];
  return {
    commands,
    release: vi.fn(),
    query: vi.fn(async (sql: string) => { commands.push(sql); return { rows: [] }; }),
    poolQuery: vi.fn(async () => ({ rows: [] as Record<string, unknown>[] })),
  };
});
vi.mock('pg', () => ({ Pool: class {
  query = poolQuery;
  async connect() { return { query, release }; }
} }));
import { PgStore } from '../../src/server/pgStore.js';

beforeEach(() => { commands.length = 0; vi.clearAllMocks(); });

describe('Postgres atomic battle writes', () => {
  it('normalizes persisted legacy snapshots without party or official record columns', async () => {
    const store = await PgStore.connect('postgres://u:p@localhost/desmon');
    const id = '00000000-0000-4000-8000-000000000001';
    poolQuery.mockResolvedValueOnce({ rows: [{ id, nickname: 'old', snapshot: { name: 'old', bestIndex: 3, rebirths: 0, companions: [] }, stolen_ids: [], last_pvp_at: null }] });
    expect(await store.getById(id)).toMatchObject({ snapshot: { party: [] }, wins: 0, losses: 0, thefts: [] });
  });

  it('uses a dedicated connection, locks writes, commits and releases', async () => {
    const store = await PgStore.connect('postgres://u:p@localhost/desmon');
    await store.transaction(async (tx) => {
      await tx.setLastPvpAt('winner', 1000);
      await tx.recordBattle('winner', 'loser');
    });
    expect(poolQuery).toHaveBeenCalledTimes(1); // DDL only; the transaction owns its client.
    expect(commands[0]).toBe('BEGIN');
    expect(commands[1]).toBe('LOCK TABLE players IN SHARE ROW EXCLUSIVE MODE');
    expect(commands[2]).toBe('UPDATE players SET last_pvp_at = $2 WHERE id = $1');
    expect(commands[3]).toContain('UPDATE players SET wins = wins +');
    expect(commands.at(-1)).toBe('COMMIT');
    expect(release).toHaveBeenCalledTimes(1);
  });

  it('rolls back all writes and releases when work fails', async () => {
    const store = await PgStore.connect('postgres://u:p@localhost/desmon');
    await expect(store.transaction(async (tx) => {
      await tx.setLastPvpAt('winner', 1000);
      throw new Error('failed roster write');
    })).rejects.toThrow('failed roster write');
    expect(commands).not.toContain('COMMIT');
    expect(commands.at(-1)).toBe('ROLLBACK');
    expect(release).toHaveBeenCalledTimes(1);
  });
});

// Real engine, injected RNG/clock, no wall time or input hooks. A simulation
// measures pacing; it cannot certify that a human finds the game enjoyable.
import { writeFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { createEngine, heroReady, mulberry32 } from '../src/core/index.js';

type Profile = 'active' | 'idle' | 'intermittent';
interface Sample { minutes: number; profile: Profile; seed: number; kills: number; firstOfferSec: number | null;
  reincarnations: number; collected: number; coins: number; companions: number; longestKillGapSec: number }

function simulate(profile: Profile, seed: number): Sample[] {
  const engine = createEngine(null, mulberry32(seed));
  const result: Sample[] = [];
  let firstOfferSec: number | null = null;
  let lastKill = 0;
  let longestKillGapSec = 0;
  for (let sec = 1; sec <= 1800; sec++) {
    // All profiles get a two-minute onboarding. Idle then stops input;
    // intermittent works 15 seconds per minute; active inputs twice a second.
    const inputs = sec <= 120 || profile === 'active' || (profile === 'intermittent' && sec % 60 < 15) ? 2 : 0;
    let killed = false;
    for (let i = 0; i < inputs; i++) {
      const hit = engine.attack('keyboard');
      killed = hit.some((e) => e.type === 'monsterKilled') || killed;
    }
    // Do not short-circuit engine steps when an earlier input killed.
    const events = engine.tick(1000);
    killed = events.some((e) => e.type === 'monsterKilled') || killed;
    if (killed) {
      longestKillGapSec = Math.max(longestKillGapSec, sec - lastKill);
      lastKill = sec;
    }
    const state = engine.getState();
    if (heroReady(state.level, state.hero)) {
      firstOfferSec ??= sec;
      engine.apply({ type: 'heroOffer' });
      const hero = engine.getState().hero!;
      // Choose the guaranteed newest visual rank, without any gold rerolls.
      engine.apply({ type: 'heroChoose', formId: hero.choices[0]!.formId, offerSerial: hero.offerSerial });
    }
    if ([300, 900, 1800].includes(sec)) {
      const current = engine.getState();
      result.push({ minutes: sec / 60, profile, seed, kills: current.killCount,
        firstOfferSec, reincarnations: current.hero?.reincarnations ?? 0,
        collected: current.hero?.collection.length ?? 0, coins: current.coins,
        companions: current.companions.length,
        longestKillGapSec: Math.max(longestKillGapSec, sec - lastKill) });
    }
  }
  return result;
}

describe('v0.4 deterministic pacing playtest', () => {
  it('checks 100 seeds across active, warm-idle and intermittent play at 5/15/30 minutes', () => {
    const samples = (['active', 'idle', 'intermittent'] as const).flatMap((profile) =>
      Array.from({ length: 100 }, (_, i) => {
        const sample = simulate(profile, i + 1);
        if (process.env.DESMON_BALANCE_REPORT && (i + 1) % 25 === 0) process.stdout.write(`${profile}: ${i + 1}/100 seeds\n`);
        return sample;
      }).flat());
    const quantiles = (values: number[]) => {
      const sorted = [...values].sort((a, b) => a - b);
      return { p10: sorted[Math.floor((sorted.length - 1) * .1)]!, p50: sorted[Math.floor((sorted.length - 1) * .5)]!, p90: sorted[Math.floor((sorted.length - 1) * .9)]! };
    };
    const scenarios = (['active', 'idle', 'intermittent'] as const).flatMap((profile) => [5, 15, 30].map((minutes) => {
      const rows = samples.filter((s) => s.profile === profile && s.minutes === minutes);
      return { profile, minutes, samples: rows.length,
        firstOfferReached: rows.filter((r) => r.firstOfferSec !== null).length,
        firstOfferSec: quantiles(rows.flatMap((r) => r.firstOfferSec === null ? [] : [r.firstOfferSec])),
        kills: quantiles(rows.map((r) => r.kills)), reincarnations: quantiles(rows.map((r) => r.reincarnations)),
        collected: quantiles(rows.map((r) => r.collected)), coins: quantiles(rows.map((r) => r.coins)),
        longestKillGapSec: quantiles(rows.map((r) => r.longestKillGapSec)),
        fullRosters: rows.filter((r) => r.companions === 30).length };
    }));
    const report = { version: '0.4.0', kind: 'simulated-not-human', seeds: '1..100',
      inputModel: '2 inputs/s; 120s onboarding, then idle=0/s; intermittent=15s/min; choose first offer, no rerolls, no companion management',
      scenarios, rawSamples: samples };
    if (process.env.DESMON_BALANCE_REPORT) writeFileSync(process.env.DESMON_BALANCE_REPORT, JSON.stringify(report, null, 2) + '\n');
    expect(samples).toHaveLength(900);
    expect(samples.every((s) => s.coins >= 0 && s.collected <= 50 && s.companions <= 30)).toBe(true);
    const active = scenarios.find((s) => s.profile === 'active' && s.minutes === 5)!;
    expect(active.firstOfferReached).toBe(100);
    expect(active.firstOfferSec.p90).toBeLessThanOrEqual(300);
    for (const profile of ['active', 'idle', 'intermittent']) {
      const early = scenarios.find((s) => s.profile === profile && s.minutes === 5)!;
      const late = scenarios.find((s) => s.profile === profile && s.minutes === 30)!;
      expect(late.kills.p50).toBeGreaterThan(early.kills.p50);
      expect(late.reincarnations.p50).toBeGreaterThan(early.reincarnations.p50);
    }
  }, 30_000);
});

import { describe, expect, it } from 'vitest';
import {
  createEngine, DEFAULT_SAVE, HERO_FORMS, HERO_DEFER_MS, HERO_MIN_LEVEL,
  heroAttackPower, heroBuffedPower, heroDamageForLevel, heroForm,
