    // With companions but no match found yet the button is still dead (F75).
    fake.emit(saveWith(COMPANIONS));
    expect(go.disabled).toBe(true);
    doc.el('find').click();
    await flush();
    expect(go.disabled).toBe(false);
    go.click();
    await flush();
