    expect(win.fake.actions).toEqual([
      { type: 'removeCompanions', ids: ['c3'] },
      {
        type: 'pvpResult',
        won: true,
        stolen: STOLEN,
        lostId: null,
        replay: { opponentName: 'Bo', opponentParty: [], blows: [] },
      },
