import { describe, expect, it } from 'vitest';
import {
  createEngine, DEFAULT_SAVE, HERO_FORMS, HERO_DEFER_MS, HERO_MIN_LEVEL,
  heroAttackPower, heroBuffedPower, heroDamageForLevel, heroForm,
  heroRerollCost, mulberry32, newHeroProgress, parseSave, serializeSave, rollHeroChoices,
} from '../src/core/index.js';
import type { SaveFile } from '../src/core/index.js';

const readySave = (): SaveFile => ({ ...DEFAULT_SAVE, level: HERO_MIN_LEVEL, coins: 1000, monsterIndex: 39, monsterHp: '1',
  companions: [{ id: 'c1', speciesId: 'dragon', bossIndex: 31, level: 3, stars: 1 }], pvpParty: ['c1'], nextCompanionId: 2 });
const readyEngine = () => createEngine(readySave(), mulberry32(4));

describe('v0.4 hero growth, collection and persistent choices', () => {
  it('gives every level a strictly larger hit and accelerates beyond the old linear curve', () => {
    expect(heroDamageForLevel(1)).toBe(1n);
    expect(heroDamageForLevel(2)).toBe(2n);
    expect(heroDamageForLevel(10)).toBe(74n);
    for (let level = 2; level <= 100; level++) expect(heroDamageForLevel(level)).toBeGreaterThan(heroDamageForLevel(level - 1));
    expect(heroAttackPower(10, 2, 4)).toBe(444n);
    const engine = createEngine({ ...DEFAULT_SAVE, level: 10 }, { next: () => .99 });
    expect(engine.attack('keyboard')[0]).toMatchObject({ type: 'attack', damage: 74n });
  });
  it('defines 50 fixed form/element/buff sets across five visual ranks', () => {
    expect(HERO_FORMS).toHaveLength(50);
    expect(new Set(HERO_FORMS.map((f) => f.id)).size).toBe(50);
    for (let rank = 1; rank <= 5; rank++) {
      const forms = HERO_FORMS.filter((f) => f.rank === rank);
      expect(forms).toHaveLength(10);
      expect(new Set(forms.map((f) => f.type)).size).toBe(5);
      expect(forms.filter((f) => f.buff === 'element')).toHaveLength(5);
    }
  });
  it('samples bounded random rolls, all 50 forms and three real elemental alternatives', () => {
    const rng = mulberry32(404);
    const hero = { ...newHeroProgress(), reincarnations: 4 };
    const seen = new Set<string>();
    const values: number[] = [];
    for (let i = 0; i < 1000; i++) {
      const choices = rollHeroChoices(hero, rng);
      expect(new Set(choices.map((r) => heroForm(r.formId)!.type)).size).toBe(3);
      expect(heroForm(choices[0]!.formId)!.rank).toBe(5);
      for (const roll of choices) { seen.add(roll.formId); values.push(roll.buffPercent); }
    }
    expect(seen.size).toBe(50);
    expect(Math.min(...values)).toBe(10);
    expect(Math.max(...values)).toBe(25);
    const mean = values.reduce((sum, x) => sum + x, 0) / values.length;
    expect(mean).toBeGreaterThan(17.2);
    expect(mean).toBeLessThan(17.8);
  });
  it('bounds mature one-shot parties to one successful reincarnation per two minutes', () => {
    const companions = ['slime', 'bat', 'ghost', 'golem', 'dragon'].map((speciesId, i) => ({ id: `c${i + 1}`, speciesId,
      bossIndex: 80, level: 10, stars: 3 }));
    const engine = createEngine({ ...DEFAULT_SAVE, level: 12, companions, nextCompanionId: 6 }, mulberry32(12345));
    const times: number[] = [];
    for (let sec = 0; sec <= 360; sec++) {
      if (sec > 0) engine.tick(1000);
      engine.apply({ type: 'heroOffer' });
      const hero = engine.getState().hero;
      if (hero?.choices.length) {
        engine.apply({ type: 'heroChoose', formId: hero.choices[0]!.formId, offerSerial: hero.offerSerial });
        times.push(sec);
      }
    }
    expect(times).toEqual([0, 120, 240, 360]);
  });
  it('requires the unlock, rolls 3 different elements and persists the exact offer on reload', () => {
    const locked = createEngine({ ...DEFAULT_SAVE, level: HERO_MIN_LEVEL - 1 }, mulberry32(4));
    locked.apply({ type: 'heroOffer' });
    expect(locked.getState().hero).toBeUndefined();
    const engine = readyEngine();
    engine.apply({ type: 'heroOffer' });
    const offered = engine.toSave();
    expect(offered.hero?.choices).toHaveLength(3);
    expect(new Set(offered.hero?.choices.map((c) => heroForm(c.formId)?.type)).size).toBe(3);
    const resumed = createEngine(parseSave(serializeSave(offered)), mulberry32(987));
    resumed.apply({ type: 'heroOffer' });
    expect(resumed.toSave()).toEqual(offered);
    for (const c of offered.hero!.choices) expect(c.buffPercent).toBeGreaterThanOrEqual(10);
  });
  it('spends exactly once on a current offer, refuses insufficient gold and stale double clicks', () => {
    const engine = readyEngine();
    engine.apply({ type: 'heroOffer' });
    const offered = engine.toSave().hero!;
    engine.apply({ type: 'heroReroll', offerSerial: offered.offerSerial });
    expect(engine.getState().coins).toBe(1000 - heroRerollCost(0));
    const rerolled = engine.toSave();
    engine.apply({ type: 'heroReroll', offerSerial: offered.offerSerial });
    engine.apply({ type: 'heroChoose', formId: offered.choices[0]!.formId, offerSerial: offered.offerSerial });
    expect(engine.toSave()).toEqual(rerolled);
    const poor = createEngine({ ...rerolled, coins: 49 }, mulberry32(7));
    const before = poor.toSave();
    poor.apply({ type: 'heroReroll', offerSerial: rerolled.hero!.offerSerial });
    expect(poor.toSave()).toEqual(before);
  });
  it('deferring preserves progress and enables a free new opportunity after 30 injected seconds, including reload', () => {
    const engine = createEngine({ ...readySave(), companions: [], pvpParty: [] }, mulberry32(4));
    engine.apply({ type: 'heroOffer' });
    engine.apply({ type: 'heroDefer', offerSerial: engine.getState().hero!.offerSerial });
    expect(engine.getState()).toMatchObject({ level: HERO_MIN_LEVEL, coins: 1000, hero: { choices: [], deferRemainingMs: HERO_DEFER_MS } });
    engine.tick(17.5);
    const resumed = createEngine(parseSave(serializeSave(engine.toSave())), mulberry32(9));
    resumed.apply({ type: 'heroOffer' });
    expect(resumed.getState().hero!.choices).toHaveLength(0);
    resumed.tick(29_982);
    expect(resumed.getState().hero!.choices).toHaveLength(0);
    expect(resumed.tick(1)).toContainEqual({ type: 'heroReady' });
    resumed.apply({ type: 'heroOffer' });
    expect(resumed.getState().hero!.choices).toHaveLength(3);
    expect(resumed.getState().coins).toBe(1000);
  });
  it('only acceptance resets the run, retains possessions, equips and raises the next visual rank', () => {
    const engine = readyEngine();
    engine.apply({ type: 'heroOffer' });
    const before = engine.toSave();
    const choice = before.hero!.choices[0]!;
    engine.apply({ type: 'heroChoose', formId: 'h50', offerSerial: before.hero!.offerSerial });
    expect(engine.toSave()).toEqual(before);
    expect(engine.apply({ type: 'heroChoose', formId: choice.formId, offerSerial: before.hero!.offerSerial })).toContainEqual({ type: 'rebirth', souls: 4 });
    const accepted = engine.toSave();
    expect(accepted).toMatchObject({ level: 1, xp: 0, monsterIndex: 0, coins: before.coins, companions: before.companions,
      pvpParty: before.pvpParty, hero: { equipped: choice, collection: [choice], reincarnations: 1, choices: [] } });
    const next = createEngine({ ...accepted, level: HERO_MIN_LEVEL, companions: [], pvpParty: [] }, mulberry32(3));
    next.apply({ type: 'heroOffer' });
    expect(next.getState().hero!.choices).toHaveLength(0);
    next.tick(120_000);
    next.apply({ type: 'heroOffer' });
    expect(heroForm(next.getState().hero!.choices[0]!.formId)?.rank).toBe(2);
    const saved = next.toSave();
    saved.hero!.collection[0]!.buffPercent = 999;
    expect(next.getState().hero!.collection[0]!.buffPercent).toBe(choice.buffPercent);
  });
  it('equips only collected skins and keeps their fixed roll without resetting the run', () => {
    const hero = { ...newHeroProgress(), equipped: { formId: 'h01', buffPercent: 10 },
      collection: [{ formId: 'h01', buffPercent: 10 }, { formId: 'h09', buffPercent: 25 }] };
    const engine = createEngine({ ...readySave(), hero }, mulberry32(2));
    engine.apply({ type: 'heroEquip', formId: 'h50' });
    expect(engine.getState().hero!.equipped.formId).toBe('h01');
    engine.apply({ type: 'heroEquip', formId: 'h09' });
    expect(engine.getState()).toMatchObject({ level: HERO_MIN_LEVEL, coins: 1000, hero: { equipped: { formId: 'h09', buffPercent: 25 } } });
  });
  it('retains the best roll on duplicates instead of downgrading an owned form', () => {
    const hero = { ...newHeroProgress(), collection: [{ formId: 'h01', buffPercent: 25 }],
      choices: [{ formId: 'h01', buffPercent: 10 }, { formId: 'h02', buffPercent: 15 }, { formId: 'h03', buffPercent: 20 }], offerSerial: 1 };
    const engine = createEngine({ ...readySave(), hero }, mulberry32(2));
    engine.apply({ type: 'heroChoose', formId: 'h01', offerSerial: 1 });
    expect(engine.getState().hero!.equipped).toEqual({ formId: 'h01', buffPercent: 25 });
    expect(engine.getState().hero!.collection).toHaveLength(1);
  });
  it('specialists and generalists produce different useful parties, without a rarity multiplier', () => {
    expect(heroBuffedPower(100n, 'fire', { formId: 'h01', buffPercent: 25 })).toBe(150n);
    expect(heroBuffedPower(100n, 'water', { formId: 'h01', buffPercent: 25 })).toBe(100n);
    expect(heroBuffedPower(100n, 'water', { formId: 'h06', buffPercent: 25 })).toBe(125n);
    expect(heroBuffedPower(100n, 'fire', { formId: 'h41', buffPercent: 25 })).toBe(150n);
    expect(heroBuffedPower(100n, 'fire', { formId: 'h01', buffPercent: 99 })).toBe(100n);
  });
  it('validates malformed hero fields independently and never changes legacy progress', () => {
    const legacy = readySave();
    expect(parseSave(serializeSave(legacy))).toEqual(legacy);
    const parsed = parseSave({ ...legacy, hero: { equipped: { formId: 'h50', buffPercent: 100 },
      collection: [{ formId: 'h01', buffPercent: 10 }, { formId: 'h01', buffPercent: 25 }, { formId: '__proto__', buffPercent: 10 }],
      choices: [{ formId: 'h50', buffPercent: 20 }], deferRemainingMs: Infinity, reincarnations: -1 } });
    expect(parsed.hero).toMatchObject({ equipped: { formId: 'h00', buffPercent: 0 }, collection: [{ formId: 'h01', buffPercent: 25 }], choices: [], reincarnations: 0, deferRemainingMs: 0 });
    expect(parsed.coins).toBe(legacy.coins);
    expect(parsed.companions).toEqual(legacy.companions);
  });
});

import { describe, expect, it } from 'vitest';
import { HERO_FORMS } from '../src/core/hero.js';
import { heroAttack, heroIdle } from '../src/renderer/sprites/hero.js';
import { drawHeroForm, HERO_FORM_IDS, heroFormSprite } from '../src/renderer/sprites/heroForms.js';
import { allSprites, drawSprite } from '../src/renderer/sprites/sprite.js';
import type { SpriteCanvas } from '../src/renderer/sprites/sprite.js';

function canvas(): { ctx: SpriteCanvas; pixels: unknown[] } {
  const pixels: unknown[] = [];
  const ctx = {
    fillStyle: '',
    fillRect(x: number, y: number, w: number, h: number): void {
      pixels.push([x, y, w, h, ctx.fillStyle]);
    },
  };
  return { ctx, pixels };
}

describe('v0.4 reincarnated hero art', () => {
  it('supplies 50 complete registered 32×32 forms with animated idle and attack poses', () => {
    expect(HERO_FORM_IDS).toHaveLength(50);
    expect(HERO_FORM_IDS).toEqual(HERO_FORMS.map((form) => form.id));
    expect(HERO_FORM_IDS[0]).toBe('h01');
    expect(HERO_FORM_IDS[49]).toBe('h50');
    for (const id of HERO_FORM_IDS) {
      const idle = heroFormSprite(id);
      const attack = heroFormSprite(id, true);
      expect(idle.frames, id).toHaveLength(2);
      expect(attack.frames, id).toHaveLength(3);
      expect(allSprites().get(`hero.${id}.idle`)).toBe(idle);
      expect(allSprites().get(`hero.${id}.attack`)).toBe(attack);
      const poses = [...idle.frames, ...attack.frames];
      expect(new Set(poses.map((rows) => rows.join('/'))).size, `${id}: animated poses`).toBe(5);
      for (const sprite of [idle, attack]) {
        expect([sprite.w, sprite.h]).toEqual([32, 32]);
        for (const color of Object.values(sprite.palette)) expect(color).toMatch(/^#[0-9a-f]{6}$/);
        for (const rows of sprite.frames) {
          expect(rows, id).toHaveLength(32);
          for (const row of rows) {
            expect(row.length, id).toBe(32);
            for (const char of row.replaceAll('.', '')) expect(sprite.palette[char], `${id} color ${char}`).toBeDefined();
          }
          expect(rows[31]?.replaceAll('.', '').length, `${id}: feet stay grounded`).toBeGreaterThan(0);
        }
      }
    }
  });

  it('all 50 silhouettes differ even after erasing every color', () => {
    const masks = new Map<string, string>();
    for (const id of HERO_FORM_IDS) {
      const mask = heroFormSprite(id).frames[0]?.map((row) => row.replace(/[^.]/g, '#')).join('/');
      expect(mask).toBeDefined();
      expect(masks.get(mask ?? ''), `${id} duplicates another form`).toBeUndefined();
      masks.set(mask ?? '', id);
    }
    expect(masks.size).toBe(50);
  });

  it('each family gains visible equipment at every rank, not just palette swaps', () => {
    for (let family = 0; family < 10; family++) {
      let previousArea = 0;
      for (let rank = 0; rank < 5; rank++) {
        const id = HERO_FORM_IDS[rank * 10 + family] ?? '';
        const pixels = heroFormSprite(id).frames[0]?.join('').replaceAll('.', '').length ?? 0;
        expect(pixels, `${id} rank ${rank + 1} equipment`).toBeGreaterThan(previousArea + 8);
        previousArea = pixels;
      }
    }
  });

  it('the card helper uses the same art and integer scale / mirror / tint as world drawing', () => {
    const preview = canvas();
    const world = canvas();
    const options = { scale: 2, flipX: true, tint: '#ffffff' };
    drawHeroForm(preview.ctx, 'h50', 7, 13, options);
    drawSprite(world.ctx, heroFormSprite('h50'), 0, 7, 13, options);
    expect(preview.pixels.length).toBeGreaterThan(0);
    expect(preview.pixels).toEqual(world.pixels);
  });

  it('unknown saved form IDs fall back to the novice in both animation states', () => {
    expect(heroFormSprite('missing')).toBe(heroIdle);
    expect(heroFormSprite('__proto__', true)).toBe(heroAttack);
  });
});

import { describe, expect, it } from 'vitest';
import { createEngine, DEFAULT_SAVE, mulberry32 } from '../src/core/index.js';
import { newHeroProgress } from '../src/core/hero.js';
import { ATTACK_FRAME_MS, createGame, IDLE_FRAME_MS } from '../src/renderer/game.js';
import type { GameCanvas } from '../src/renderer/game.js';
import { COLORS } from '../src/renderer/sprites/palette.js';

function gameFor(formId: string): ReturnType<typeof createGame> {
  const roll = { formId, buffPercent: formId === 'h00' ? 0 : 20 };
  return createGame(createEngine({
    ...DEFAULT_SAVE,
    hero: { ...newHeroProgress(), equipped: roll, collection: formId === 'h00' ? [] : [roll], reincarnations: 5 },
  }, mulberry32(7)));
}

interface Pixel { x: number; y: number; w: number; h: number; color: string }
function draw(game: ReturnType<typeof createGame>): Pixel[] {
  const pixels: Pixel[] = [];
  const ctx: GameCanvas = {
    fillStyle: '',
    fillRect(x, y, w, h): void { pixels.push({ x, y, w, h, color: String(ctx.fillStyle) }); },
    clearRect(): void { pixels.length = 0; },
  };
  game.draw(ctx);
  return pixels;
}

describe('reincarnated hero field placement', () => {
  it('keeps the XP bar near each visible crown, stable through idle and wind-up', () => {
    // Actual crown pixels begin at y=92 (novice), 80 (first form), 58 (mythic).
    // A 4px XP frame ends two pixels above each crown, rather than above its padding.
    for (const [id, barY] of [['h00', 86], ['h01', 74], ['h41', 52]] as const) {
      const game = gameFor(id);
      const expected = { x: 60, y: barY, w: 40, h: 4, color: COLORS.steel };
      expect(draw(game), `${id} idle`).toContainEqual(expected);
      game.update(IDLE_FRAME_MS);
      expect(draw(game), `${id} breathing`).toContainEqual(expected);
      game.attack('keyboard');
      expect(draw(game), `${id} wind-up`).toContainEqual(expected);
    }
  });

  it('puts the slash beyond the evolved blade and suppresses it in a PvP replay', () => {
    const game = gameFor('h41');
    game.attack('keyboard');
    game.update(ATTACK_FRAME_MS);
    // The 32px hero is centered at x=80, so its blade ends at x=112. The
    // cyan outer arc starts one art pixel beyond it, at x=114 (legacy x=96).
    const arc = { x: 114, y: 98, w: 2, h: 2, color: COLORS.cyan };
    expect(draw(game)).toContainEqual(arc);
    expect(draw(game)).not.toContainEqual({ ...arc, x: 96 });
    game.playReplay({ opponentName: 'FOE', opponentParty: [], blows: [] });
    expect(draw(game)).not.toContainEqual(arc);
  });
});

// Menu DOM binder — SPEC F54/F55/F75 (Assumption 29; GAME_DESIGN_V2 §9,
// GAME_DESIGN_V3 §7). A thin binder over src/menu/view.ts: it owns no game
// state, it renders the save main sends and forwards every button press as a
// CollectionAction.
//
// DOM-free by injection (same policy as renderer/input.ts): mountMenu takes
// the document and the preload bridge as parameters — production passes the
// real globals in the boot at the bottom, tests pass fakes — so it runs under
// vitest's node environment. The menu NEVER imports electron or net; the
// bridge is its only way out.

import {
  autoParty,
  DEFAULT_SAVE,
  heroReady,
  heroRerollCost,
  isSpeciesId,
  parseSave,
  PARTY_SIZE,
  pvpParty,
  SPECIES_IDS,
} from '../core/index.js';
import type { CollectionAction, Companion, SaveFile, SpeciesId } from '../core/index.js';
import { drawSprite, monsterSprites, paletteForTier } from '../renderer/sprites/index.js';
import type { SpriteCanvas } from '../renderer/sprites/index.js';
import type {
  IdentityPayload,
  LeaderboardResult,
  MatchResult,
  NetResult,
  OpponentListResult,
  OpponentSummary,
  PvpResult,
  ReclaimResult,
  Theft,
  TheftsResult,
} from '../shared/api.js';
import {
  battleEnabled,
  canRebirth,
  consumeTargets,
  fuseCandidates,
  leaderboardRows,
  miniRow,
  opponentRows,
  partyPreview,
  pvpResultText,
  rosterRows,
  theftRows,
  togglePick,
} from './view.js';
import type { MiniRow, RankRow, RosterRow, TheftRow } from './view.js';
import { heroPanel, heroCanvas } from './hero.js';

/** The element surface this page touches — a real DOM element satisfies it. */
export interface MenuElement {
  className: string;
  textContent: string | null;
  hidden: boolean;
  disabled?: boolean;
  /** The name field's text; absent on everything else. */
  value?: string;
  width?: number;
  height?: number;
  /** Native details disclosure state, preserved across live save updates. */
  open?: boolean;
  append(...children: unknown[]): void;
  replaceChildren(...children: unknown[]): void;
  addEventListener(type: 'click' | 'change', listener: () => void): void;
  getContext?(id: '2d'): SpriteCanvas | null;
}

/** The document surface this page touches — the real `document` satisfies it. */
export interface MenuDocument {
  createElement(tag: string): MenuElement;
  querySelector(selectors: string): MenuElement | null;
}

/** The slice of window.desmon this page needs (src/renderer/global.d.ts). */
export interface MenuBridge {
  reportMenuReady(): void;
  onStateChanged(cb: (save: unknown) => void): () => void;
  sendAction(a: CollectionAction): Promise<void>;
  getIdentity(): Promise<IdentityPayload>;
  setName(name: string): Promise<IdentityPayload>;
  getLeaderboard(n?: number): Promise<NetResult<LeaderboardResult>>;
  pvpOpponents?(): Promise<NetResult<OpponentListResult>>;
  pvpMatch(opponentId?: string): Promise<NetResult<MatchResult>>;
  pvp(matchId: string, party: string[]): Promise<NetResult<PvpResult>>;
  thefts(): Promise<NetResult<TheftsResult>>;
  reclaim(theftId: string): Promise<NetResult<ReclaimResult>>;
}

/** Tab ids — each is both the tab button (`#tab-<id>`) and its panel (`#<id>`). */
const PANELS = ['hero', 'roster', 'ranking', 'battle'] as const;

/**
 * Card art: species idle frame at the uniform 1x scale (2026-09-04) on a fixed
 * buffer sized to the LARGEST species, each smaller species centred + bottom-
 * aligned. CSS (`canvas.species`) scales the buffer to the on-screen card, so
 * bigger species read bigger in the menu too.
 */
const CARD_SCALE = 1;
const CARD_W = Math.max(...SPECIES_IDS.map((id) => monsterSprites[id].idle.w));
const CARD_H = Math.max(...SPECIES_IDS.map((id) => monsterSprites[id].idle.h));

/** NICK_RE's ceiling — the name field also carries it as `maxlength`. */
const NAME_MAX = 16;

/** The `#opponent` panel before the first `Find opponent` (F75). */
const NO_OPPONENT = 'No opponent yet';

/** A half-finished two-companion action, waiting for its partner card. */
interface Pending {
  kind: 'consume' | 'fuse';
  id: string;
}

/** Species art key for a runtime species id (unknown ids fall back to slime). */
function speciesKey(speciesId: string): SpeciesId {
  return isSpeciesId(speciesId) ? speciesId : SPECIES_IDS[0];
}

/**
 * Bind the Collection & Battle page: boot reports the menu ready, every
 * `desmon:state-changed` re-renders the roster, and the card buttons send
 * consume/fuse/reincarnate/sacrifice/rebirth back through the bridge.
 * Ranking loads on tab open; Battle names the player, finds an opponent
 * (`pvpMatch`), edits the party and fights it (`pvp`), then plays the theft
 * inbox — all of them take the identity's `online` flag as their offline
 * answer, so a server-less build never calls the network. Roster changes the
 * server made (`removed`, the stolen companion, a reclaim) reach the game ONLY
 * from here, as actions.
 */
export function mountMenu(doc: MenuDocument, api: MenuBridge): void {
  const roster = doc.querySelector('#roster');
  const heroEl = doc.querySelector('#hero');
  const rebirthBtn = doc.querySelector('#rebirth');
  const result = doc.querySelector('#result');
  const ranking = doc.querySelector('#ranking');
  const nameField = doc.querySelector('#name');
  const battleBtn = doc.querySelector('#battle-go');
  const findBtn = doc.querySelector('#find');
  const opponentEl = doc.querySelector('#opponent');
  const opponentsEl = doc.querySelector('#opponents');
  const partyEl = doc.querySelector('#party');
  const picksEl = doc.querySelector('#picks');
  const autoBtn = doc.querySelector('#auto');
  const savePartyBtn = doc.querySelector('#save-party');
  const previewEl = doc.querySelector('#preview');
  const theftsEl = doc.querySelector('#thefts');
  // The page ships its own markup (static/menu.html); without it there is
  // nothing to bind and nothing to report ready for.
  if (
    !roster ||
    !rebirthBtn ||
    !result ||
    !ranking ||
    !nameField ||
    !battleBtn ||
    !findBtn ||
    !opponentEl ||
    !partyEl ||
    !picksEl ||
    !autoBtn ||
    !savePartyBtn ||
    !previewEl ||
    !theftsEl
  ) {
    return;
  }

  let save: SaveFile = DEFAULT_SAVE;
  let pending: Pending | null = null;
  let rank: NetResult<LeaderboardResult> | null = null;
  /** The previewed opponent — null before `Find opponent`, or once it expired. */
  let match: MatchResult | null = null;
  let opponents: OpponentSummary[] = [];
  let directoryNote = '상대 목록을 불러오세요.';
  let directoryLoading = false;
  let matchLoading = false;
  let battleLoading = false;
  /** What the `#opponent` panel says while no match is loaded. */
  let opponentNote = NO_OPPONENT;
  /** The ids picked for my party, and the saved party they were synced from. */
  let picked: string[] = [];
  let syncedIds = '';
  let inbox: readonly Theft[] = [];
  /** Seconds left on the PvP cooldown; `ticker` runs while it counts down. */
  let cooldown = 0;
  let ticker: unknown = null;
  // One identity call per page: its `name` fills the field and its `online`
  // decides whether a tab may touch the network at all.
  const identity = api.getIdentity();

  const tabs = PANELS.map((id) => ({
    id,
    tab: doc.querySelector(`#tab-${id}`),
    panel: doc.querySelector(`#${id}`),
  }));
  for (const t of tabs) {
    t.tab?.addEventListener('click', () => {
      for (const other of tabs) {
        if (other.tab) other.tab.className = other.id === t.id ? 'tab active' : 'tab';
        if (other.panel) other.panel.hidden = other.id !== t.id;
      }
      if (t.id === 'ranking') openRanking();
      if (t.id === 'battle') {
        loadThefts();
        if (api.pvpOpponents) loadOpponents();
      }
    });
  }

  const span = (className: string, text: string): MenuElement => {
    const e = doc.createElement('span');
    e.className = className;
    e.textContent = text;
    return e;
  };

  const div = (className: string, ...children: MenuElement[]): MenuElement => {
    const e = doc.createElement('div');
    e.className = className;
    e.append(...children);
    return e;
  };

  // Autosaves update numbers frequently. Keep the gallery and actionable
  // choices mounted so scrolling, keyboard focus and an open details survive.
  const heroSections = heroEl ? [div('hero-heading'), div('hero-controls'), div('hero-catalog')] : [];
  heroEl?.replaceChildren(...heroSections);
  let heroControlsKey = '';
  let heroGalleryKey = '';
  let heroGallery: MenuElement | undefined;

  // A disabled button carries no listener: the page re-renders after every
  // action, so a stale handler can never fire.
  const button = (label: string, disabled: boolean, onClick: () => void): MenuElement => {
    const b = doc.createElement('button');
    b.className = 'btn';
    b.textContent = label;
    b.disabled = disabled;
    if (!disabled) b.addEventListener('click', onClick);
    return b;
  };

  const send = (a: CollectionAction): void => {
    pending = null;
    result.textContent = '';
    void api.sendAction(a);
    render();
  };

  const select = (kind: Pending['kind'], row: RosterRow, hint: string): void => {
    pending = { kind, id: row.id };
    result.textContent = `${hint} ${row.name}.`;
    render();
  };

  const cancel = (): void => {
    pending = null;
    result.textContent = '';
    render();
  };

  const speciesCanvas = (row: { speciesId: string; stars: number }): MenuElement => {
    const canvas = doc.createElement('canvas');
    canvas.className = 'species';
    canvas.width = CARD_W;
    canvas.height = CARD_H;
    const ctx = canvas.getContext?.('2d');
    if (ctx) {
      const idle = monsterSprites[speciesKey(row.speciesId)].idle;
      // Stars are the card's palette tier, the way monster tiers tint the
      // overlay art (GAME_ARCHITECTURE §4); DrawSpriteOptions has no palette.
      const tinted = { ...idle, palette: paletteForTier(idle.palette, row.stars) };
      const dx = Math.floor((CARD_W - idle.w) / 2);
      drawSprite(ctx, tinted, 0, dx, CARD_H - idle.h, { scale: CARD_SCALE });
    }
    return canvas;
  };

  /** The companion behind a card — its type badge comes from the live roster. */
  const byId = (id: string): Companion | undefined => save.companions.find((c) => c.id === id);

  /** The saved PvP party (auto until the player saves one of their own). */
  const savedParty = (): Companion[] => pvpParty(save.companions, save.pvpParty, save.hero?.equipped);

  const card = (row: RosterRow): MenuElement => {
    const isPending = pending?.id === row.id;
    const fusable = fuseCandidates(save).some(([a, b]) =>
      pending === null ? a === row.id || b === row.id : isPair(pending.id, row.id, a, b),
    );

    const consume =
      pending?.kind === 'consume'
        ? isPending
          ? button('Cancel', false, cancel)
          : button('Feed', !consumeTargets(save, row.id).includes(pending.id), () => {
              if (pending) send({ type: 'consume', targetId: pending.id, foodId: row.id });
            })
        : button('Consume', pending !== null || consumeTargets(save, row.id).length === 0, () => {
            select('consume', row, 'Pick a companion to feed to');
          });

    const fuse =
      pending?.kind === 'fuse'
        ? isPending
          ? button('Cancel', false, cancel)
          : button('Fuse!', !fusable, () => {
              if (pending) send({ type: 'fuse', aId: pending.id, bId: row.id });
            })
        : button('Fuse', pending !== null || !fusable, () => {
            select('fuse', row, 'Pick the twin of');
          });

    const buttons = div(
      'row',
      consume,
      fuse,
      button('Reincarnate', pending !== null || !row.maxLevel, () => {
        send({ type: 'reincarnate', id: row.id });
      }),
      button('Sacrifice', pending !== null, () => {
        send({ type: 'sacrifice', id: row.id });
      }),
    );

    const c = byId(row.id);
    const el = doc.createElement('div');
    el.className = 'card';
    el.append(
      speciesCanvas(row),
      span('name', row.name),
      span('stars', row.starText),
      span('power', row.power),
      // v3 (F75): the elemental badge, and the mark of a PvP party member.
      ...(c ? [span(miniRow(c).typeClass, miniRow(c).typeBadge)] : []),
      ...(savedParty().some((m) => m.id === row.id) ? [span('pvp-mark', '★ PvP')] : []),
      buttons,
    );
    return el;
  };

  const rankRow = (r: RankRow): MenuElement => {
    // ponytail: the leaderboard borrows the card's styled columns — `.power`
    // is the right-aligned number, `.stars` the small badge — instead of new CSS.
    return div(
      'row',
      span('rank', r.rank),
      span('name', r.name),
      span('power', r.deepest),
      span('stars', r.rebirths),
    );
  };

  /** A `.card.mini`; `pick` makes it a roster toggle button (F75 §3). */
  const miniCard = (m: MiniRow, pick = false): MenuElement => {
    const el = doc.createElement(pick ? 'button' : 'div');
    el.className = pick && picked.includes(m.id) ? 'card mini pick selected' : pick ? 'card mini pick' : 'card mini';
    el.append(
      speciesCanvas(m),
      span('name', m.name),
      span('stars', m.starText),
      span(m.typeClass, m.typeBadge),
    );
    if (pick) {
      el.addEventListener('click', () => {
        picked = togglePick(picked, m.id);
        render();
      });
    }
    return el;
  };

  /** The `#opponent` panel: the previewed party, the bot line, or the note. */
  const opponentPanel = (): MenuElement[] => {
    if (match === null) return [span('name', opponentNote)];
    if (match.bot) return [span('name', 'Training Dummy (no party)')];
    const { name, bestIndex, rebirths } = match.opponent;
    return [
      ...(match.opponent.hero ? [heroCanvas(doc, match.opponent.hero.formId)] : []),
      span('name', name),
      span('power', `Monster ${String(bestIndex)}`),
      span('stars', `♻×${String(rebirths)}`),
      div('party', ...opponentRows(match).map((m) => miniCard(m))),
    ];
  };

  const theftRow = (t: TheftRow): MenuElement =>
    div(
      'row',
      span('name', t.text),
      button('Reclaim', false, () => {
        reclaim(t.id);
      }),
    );

  const render = (): void => {
    if (heroEl) {
      const parts = heroPanel(doc, save, send);
      heroSections[0]?.replaceChildren(parts[0]);
      const controlsKey = JSON.stringify([save.hero?.choices, save.hero?.offerSerial,
        save.hero?.reincarnations, save.hero?.deferRemainingMs, save.hero?.restRemainingMs,
        heroReady(save.level, save.hero), save.coins >= heroRerollCost(save.hero?.reincarnations ?? 0)]);
      if (controlsKey !== heroControlsKey) {
        heroControlsKey = controlsKey;
        heroSections[1]?.replaceChildren(parts[1]);
      }
      const galleryKey = JSON.stringify([save.hero?.equipped, save.hero?.collection]);
      if (galleryKey !== heroGalleryKey) {
        heroGalleryKey = galleryKey;
        const open = heroGallery?.open ?? false;
        heroGallery = parts[2];
        if (heroGallery) heroGallery.open = open;
        heroSections[2]?.replaceChildren(heroGallery);
      }
    }
    const rows = rosterRows(save);
    roster.replaceChildren(
      ...(rows.length >= 30 ? [span('muted', '동료 30/30 · 보관함이 가득 찼습니다. Consume / Fuse / Sacrifice로 자리를 만들면 새 보스 동료를 포획할 수 있습니다.')] : []),
      ...(rows.length === 0
        ? [span('row', 'No companions yet — beat a boss to capture one.')]
        : rows.map(card)),
    );
    rebirthBtn.disabled = !canRebirth(save);
    ranking.replaceChildren(...(rank === null ? [] : leaderboardRows(rank).map(rankRow)));

    // Battle tab (F75): opponent preview, party editor, live preview, inbox.
    opponentEl.replaceChildren(...opponentPanel());
    opponentsEl?.replaceChildren(...(opponents.length === 0 ? [span('muted', directoryNote)] : opponents.map((opponent) => {
      const row = div('opponent-card', heroCanvas(doc, opponent.hero.formId),
        span('name', `#${opponent.rank} ${opponent.name}`),
        span('record', `${opponent.wins}승 ${opponent.losses}패`),
        span('muted', `최고 몬스터 ${opponent.bestIndex}`),
        div('party', ...opponent.party.map((c) => miniCard(miniRow(c)))),
        button('상대 선택 · 파티 미리보기', matchLoading || battleLoading, () => find(opponent.playerId)));
      return row;
    })));
    findBtn.disabled = directoryLoading || matchLoading || battleLoading;
    partyEl.replaceChildren(
      ...Array.from({ length: PARTY_SIZE }, (_, i) => {
        const c = picked[i] === undefined ? undefined : byId(picked[i]);
        return div('slot', ...(c ? [miniCard(miniRow(c))] : []));
      }),
    );
    picksEl.replaceChildren(...save.companions.map((c) => miniCard(miniRow(c), true)));
    previewEl.textContent = partyPreview(
      picked.flatMap((id) => byId(id) ?? []),
      match?.opponent.party ?? [],
      save.hero?.equipped,
    );
    theftsEl.replaceChildren(...theftRows(inbox, Date.now()).map(theftRow));
    battleBtn.textContent = cooldown > 0 ? `Battle! (${String(cooldown)}s)` : 'Battle!';
    battleBtn.disabled = battleLoading || matchLoading || !battleEnabled({ match, party: picked, cooldownUntil: cooldown });
  };

  /** Fire-and-forget bridge call: a rejected invoke must not break the page. */
  const settle = <T>(p: Promise<T>, use: (value: T) => void): void => {
    void p.then(use, () => undefined);
  };

  /** Run `fn` only when the server is reachable; otherwise answer `offline`. */
  const online = (fn: () => void, offline: () => void): void => {
    settle(identity, (id) => {
      if (id.online) fn();
      else offline();
    });
  };

  /** The server stripped these companions from my roster — tell the game. */
  const forwardRemoved = (removed: string[]): void => {
    if (removed.length > 0) void api.sendAction({ type: 'removeCompanions', ids: removed });
  };

  /** Client countdown from the server's retryAfterSec; 0 re-arms the button. */
  const startCooldown = (sec: number): void => {
    cooldown = Math.max(0, Math.ceil(sec));
    if (cooldown === 0 || ticker !== null) return;
    ticker = setInterval(() => {
      cooldown -= 1;
      if (cooldown <= 0) {
        clearInterval(ticker);
        ticker = null;
      }
      render();
    }, 1000);
  };

  const openRanking = (): void => {
    const show = (r: NetResult<LeaderboardResult>): void => {
      if (r.ok) forwardRemoved(r.value.removed);
      rank = r;
      render();
    };
    online(
      () => {
        settle(api.getLeaderboard(), show);
      },
      () => {
        show({ ok: false, error: 'offline' });
      },
    );
  };

  /** Step 1 of a battle (F75 §1/§2): the server picks the opponent. */
  const loadOpponents = (): void => {
    if (!api.pvpOpponents || directoryLoading || battleLoading) return;
    directoryLoading = true;
    directoryNote = '상대 목록을 불러오는 중…';
    render();
    const show = (r: NetResult<OpponentListResult>): void => {
      directoryLoading = false;
      opponents = r.ok ? r.value.opponents : [];
      directoryNote = r.ok ? '아직 대전 상대가 없습니다. 나중에 목록을 새로고침하세요.' : '서버에 연결할 수 없습니다. 목록 새로고침으로 다시 시도하세요.';
      render();
    };
    online(() => { void api.pvpOpponents!().then(show, () => show({ ok: false, error: 'network' })); },
      () => show({ ok: false, error: 'offline' }));
  };

  const find = (opponentId?: string): void => {
    if (matchLoading || battleLoading) return;
    matchLoading = true;
    match = null;
    const show = (r: NetResult<MatchResult>): void => {
      matchLoading = false;
      match = r.ok ? r.value : null;
      if (r.ok) opponentNote = NO_OPPONENT;
      result.textContent = r.ok ? '' : pvpResultText(r);
      render();
    };
    online(
      () => {
        void api.pvpMatch(opponentId).then(show, () => show({ ok: false, error: 'network' }));
      },
      () => {
        show({ ok: false, error: 'offline' });
      },
    );
    render();
  };

  /**
   * Step 2 (F55/F75 §4): the loaded match plus my picked party. A win only
   * reaches the game from here — `removed` first, then the verdict with the
   * replay the game window plays (F66).
   */
  const pvp = (): void => {
    const loaded = match;
    if (loaded === null || battleLoading) return;
    battleLoading = true;
    const show = (r: NetResult<PvpResult>): void => {
      battleLoading = false;
      if (r.ok) {
        const { win, stolen, opponent, blows, removed } = r.value;
        forwardRemoved(removed);
        void api.sendAction({
          type: 'pvpResult',
          won: win,
          stolen,
          lostId: null,
          replay: { opponentName: opponent.name, opponentParty: opponent.party, blows,
            ...(opponent.hero ? { opponentHero: opponent.hero } : {}) },
        });
        // The server consumed the match: the next battle needs a new one.
        match = null;
        loadThefts();
        if (api.pvpOpponents) loadOpponents();
      } else if (r.error === 'cooldown') {
        startCooldown(r.retryAfterSec ?? 0);
      } else if (r.error === 'expired') {
        match = null;
        opponentNote = 'Opponent expired — find again';
      }
      result.textContent = r.ok || r.error !== 'expired' ? pvpResultText(r) : '';
      render();
    };
    online(
      () => {
        void api.pvp(loaded.matchId, [...picked]).then(show, () => show({ ok: false, error: 'network' }));
      },
      () => {
        show({ ok: false, error: 'offline' });
      },
    );
    render();
  };

  /** The theft inbox (F75 §5) — refreshed on tab open and after every battle. */
  const loadThefts = (): void => {
    const show = (r: NetResult<TheftsResult>): void => {
      inbox = r.ok ? r.value.thefts : [];
      render();
    };
    online(
      () => {
        settle(api.thefts(), show);
      },
      () => {
        show({ ok: false, error: 'offline' });
      },
    );
  };

  /** Take a stolen companion back: the game gets it as an `addCompanion`. */
  const reclaim = (theftId: string): void => {
    settle(api.reclaim(theftId), (r) => {
      if (r.ok) {
        void api.sendAction({ type: 'addCompanion', companion: r.value.companion });
        loadThefts();
        return;
      }
      // Only a settled window drops the row; a network hiccup keeps it.
      if (r.error === 'expired' || r.error === 'gone') {
        inbox = inbox.filter((t) => t.id !== theftId);
        result.textContent =
          r.error === 'expired' ? 'Too late — the reclaim window closed.' : 'Gone — the thief no longer has it.';
      }
      render();
    });
  };

  rebirthBtn.addEventListener('click', () => {
    if (canRebirth(save)) send({ type: 'rebirth' });
  });

  findBtn.addEventListener('click', () => { if (api.pvpOpponents) loadOpponents(); else find(); });

  battleBtn.addEventListener('click', () => {
    if (battleEnabled({ match, party: picked, cooldownUntil: cooldown })) pvp();
  });

  autoBtn.addEventListener('click', () => {
    picked = autoParty(save.companions, save.hero?.equipped).map((c) => c.id);
    render();
  });

  savePartyBtn.addEventListener('click', () => {
    void api.sendAction({ type: 'setPvpParty', ids: [...picked] });
    render();
  });

  // The field is the only writer of the name; main validates and answers with
  // the identity it kept, so the field always shows what the server will see.
  nameField.addEventListener('change', () => {
    settle(api.setName((nameField.value ?? '').slice(0, NAME_MAX)), (id) => {
      nameField.value = id.name;
    });
  });

  settle(identity, (id) => {
    nameField.value = id.name;
  });

  api.onStateChanged((raw) => {
    // Trust boundary: the payload is whatever main read off disk.
    save = parseSave(raw);
    pending = null;
    // Re-seed the editor only when the SAVED party moved: an autosave must not
    // throw away the picks the player is still editing.
    const ids = savedParty().map((c) => c.id);
    if (ids.join(',') !== syncedIds) {
      syncedIds = ids.join(',');
      picked = ids;
    }
    render();
  });

  render();
  api.reportMenuReady();
}

/** True when the unordered pair {x, y} is the unordered pair {a, b}. */
function isPair(x: string, y: string, a: string, b: string): boolean {
  return (a === x && b === y) || (a === y && b === x);
}

// Boot. `document`/`window` are declared locally (module scope) so this file
// also compiles in the DOM-free test project, and the typeof guard keeps it
// importable from vitest's node environment.
declare const document: MenuDocument;
declare const window: { desmon: MenuBridge };
// Declared locally too: the DOM and node lib types disagree on the handle.
declare const setInterval: (cb: () => void, ms: number) => unknown;
declare const clearInterval: (handle: unknown) => void;

if (typeof document !== 'undefined') {
  mountMenu(document, window.desmon);
}
